/// <summary>
/// MPJ_7094 - kscerri - 27/07/2021
/// Class <c>METProjectReportsController_Extension</c> to call our new report using new 
/// output menu item
/// </summary>
[ExtensionOf(classStr(ProjectReportsController))]
final class METProjectReportsController_Extension
{
    #define.ReptNameMETProjActualBudget('METProjActualBudget.Report')

}

Method.Source:
    public str setReportName()
    {
        str strReportName = next setReportName();

        if (this.parmArgs().menuItemName() == menuitemoutputstr(METProjActualBudget))
        {
            strReportName = #ReptNameMETProjActualBudget;
        }

        return strReportName;
    }
